/// <summary>
/// AVA/WEN 2024/02/21
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(AVACreateTraverseTransUIBuilder))
]
    class AVACreateTraverseTransContract  implements SysOperationValidatable//, SysOperationInitializable
{
    AVATraverseNum              contractTravNum;
    ItemId                      contractItemId;
    Qty                         contractQty, contractPieceQty;
    AVATraverseBasket           contractBasketNum;
    ProdId                      contractProdId;
    UnitOfMeasureSymbol         contractProdUnit, contractPieceUnit;

}

Method.Source:
public boolean validate()
{
    boolean retVal = true;

    if (!contractTravNum)
    {
        retVal = checkFailed(strFmt("@NDX:NDXErrorFieldMustBeFilled", "@NDX:NXATraverseElement"));
    }

    if (!contractItemId)
    {
        retVal = checkFailed(strFmt("@NDX:NDXErrorFieldMustBeFilled", "@SYS12836"));
    }

    if (!contractBasketNum && !contractQty)
    {
        retVal = checkFailed(strFmt("@NDX:NDXErrorFieldMustBeFilled", "@SYS14578"));
    }

    return retVal;
}

/// <summary>
///    AVA <c>parmBusRelAccount</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>DirPartyRecId</c> as type
/// </param>
/// <returns>
///    <c>smmBusRelAccount</c> as return value
/// </returns>
[
    DataMemberAttribute('contractTravNum') ,
    SysOperationDisplayOrderAttribute('1')
]
public AVATraverseNum parmTraverseNum(AVATraverseNum _parmValue = contractTravNum)
{
    contractTravNum = _parmValue;

    return contractTravNum;
}

[
    DataMemberAttribute('contractItemId') ,
    SysOperationDisplayOrderAttribute('2')
]
public ItemId parmItemId(ItemId _parmValue = contractItemId)
{
    contractItemId = _parmValue;

    return contractItemId;
}

[
    DataMemberAttribute('contractQty') ,
    SysOperationDisplayOrderAttribute('3'), 
    SysOperationLabelAttribute("@NDX:NXAQtyInProdUnit")
]
public Qty parmQty(Qty _parmValue = contractQty)
{
    contractQty = _parmValue;

    return contractQty;
}

[
    DataMemberAttribute('contractProdUnit') ,
    SysOperationDisplayOrderAttribute('4'),
    SysOperationLabelAttribute("@NDX:NXAProdUnit")
]
public UnitOfMeasureSymbol parmProdUnit(UnitOfMeasureSymbol _parmValue = contractProdUnit)
{
    contractProdUnit = _parmValue;

    return contractProdUnit;
}

[
    DataMemberAttribute('contractPieceQty') ,
    SysOperationDisplayOrderAttribute('5'),
    SysOperationLabelAttribute("@NDX:NXAQtyInPieces")
]
public Qty parmPieceQty(Qty _parmValue = contractPieceQty)
{
    contractPieceQty = _parmValue;

    return contractPieceQty;
}

[
    DataMemberAttribute('contractPieceUnit') ,
    SysOperationDisplayOrderAttribute('6'),
    SysOperationLabelAttribute("@NDX:NXAPieces") 
]
public UnitOfMeasureSymbol parmPiecesUnit(UnitOfMeasureSymbol _parmValue = contractPieceUnit)
{
    contractPieceUnit = _parmValue;

    return contractPieceUnit;
}

[
    DataMemberAttribute('contractBasketNum'),
    SysOperationDisplayOrderAttribute('7')
]
public AVATraverseBasket parmBasketNum(AVATraverseBasket _parmValue = contractBasketNum)
{
    contractBasketNum = _parmValue;

    return contractBasketNum;
}

public ProdId parmProdId(ProdId _parmValue = contractProdId)
{
    contractProdId = _parmValue;

    return contractProdId;
}
